<?php
$editId = filter_var($_GET['edit'] ?? 0, FILTER_VALIDATE_INT) ?: 0;
$customers = db()->query('SELECT id,full_name,email,phone,created_at FROM laundry__users_tbl WHERE role=\'customer\' ORDER BY id DESC')->fetchAll();
$editing = null;
foreach ($customers as $customer) if ((int)$customer['id'] === $editId) $editing = $customer;
?>
<div class="page-heading"><div><p class="eyebrow">CUSTOMER MANAGEMENT</p><h1>จัดการลูกค้า</h1><p>เพิ่มและแก้ไขข้อมูลลูกค้า (ตัวอย่างนี้ยังไม่มีปุ่มปิดบัญชี)</p></div></div>
<div class="two-col"><section class="panel"><div class="panel-header"><h2>รายชื่อลูกค้า</h2><span class="pill"><?= count($customers) ?> คน</span></div><div class="table-wrap"><table><thead><tr><th>ชื่อ</th><th>ติดต่อ</th><th>จัดการ</th></tr></thead><tbody>
<?php foreach ($customers as $c): ?><tr><td><strong><?= e($c['full_name']) ?></strong><small class="table-muted"><?= e($c['email']) ?></small></td><td><?= e($c['phone'] ?? '—') ?></td><td><div class="row-actions"><a class="text-link" href="<?= e(url('customers', ['edit' => (int)$c['id']])) ?>">แก้ไข</a></div></td></tr><?php endforeach; ?>
<?php if (!$customers): ?><tr><td colspan="3" class="empty-cell">ยังไม่มีลูกค้า</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-header"><h2><?= $editing ? 'แก้ไขลูกค้า' : 'เพิ่มลูกค้าใหม่' ?></h2><?php if ($editing): ?><a class="text-link" href="<?= e(url('customers')) ?>">ยกเลิกแก้ไข</a><?php endif; ?></div><form method="post" action="index.php" class="form-stack form-spaced"><?= csrf_field() ?><input type="hidden" name="action" value="customer-save"><input type="hidden" name="id" value="<?= (int)($editing['id'] ?? 0) ?>"><label>ชื่อ–นามสกุล<input name="full_name" required minlength="2" maxlength="100" value="<?= e($editing['full_name'] ?? '') ?>"></label><label>อีเมล<input type="email" name="email" required maxlength="150" value="<?= e($editing['email'] ?? '') ?>"></label><label>เบอร์โทร<input name="phone" maxlength="20" value="<?= e($editing['phone'] ?? '') ?>"></label><label>รหัสผ่าน <?= $editing ? '(เว้นว่างหากไม่เปลี่ยน)' : '(อย่างน้อย 8 ตัวอักษร)' ?><input type="password" name="password" <?= $editing ? '' : 'required' ?> minlength="8" autocomplete="new-password"></label><button class="btn btn-primary btn-block" type="submit">บันทึกข้อมูลลูกค้า</button></form></section></div>
